// Reminder-Nachricht pro Termin bauen
const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  const start = new Date(d.start_time);
  const timeStr = start.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });

  const message = `Hallo ${d.client_name} 👋

Kurze Erinnerung an deinen Termin morgen:

📅 ${start.toLocaleDateString('de-DE', { weekday: 'long', day: 'numeric', month: 'long' })}
🕐 ${timeStr} Uhr
💇 ${d.service_name}
👤 bei ${d.staff_name}
📍 ${d.salon_name}

Bitte bestätige mit ✅ oder verschiebe mit 🔄

Bis morgen! 😊`;

  results.push({
    json: {
      ...d,
      message,
      time_str: timeStr
    }
  });
}

return results;

